<script setup lang="ts">
import CountryPicker from '@/components/ui/CountryPicker.vue'
import DateSortHeader from '@/components/ui/DateSortHeader.vue'
import { onMounted, onBeforeUnmount, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { useI18n } from 'vue-i18n'
import { type StoreLead, type RegisterLeadInput, type LeadImportResult } from '@/api/autoflow'
import { crmMockAutoflowApi as autoflowApi } from '@/mocks/crm'
import GenerateOpportunityButton from '@/components/opportunities/GenerateOpportunityButton.vue'
import { StatusBadge } from '@/components/ui'
import { withReturnTo } from '@/composables/useReturnNavigation'
const {t}=useI18n(),route=useRoute()
const types={manual:'手工录入',import:'批量导入',automatic:'自动任务'}
const rows=ref<StoreLead[]>([]),total=ref(0),page=ref(1),pageSize=ref(100),busy=ref(false),saving=ref(false),showForm=ref(false),error=ref(''),notice=ref(''),importResult=ref<LeadImportResult>()
const search=ref(''),status=ref(String(route.query.status||'')),leadType=ref(''),fileInput=ref<HTMLInputElement>()
const draft=reactive<RegisterLeadInput>({brandName:'',country:'',storeUrl:''})
const sortBy = ref<'registeredOn' | 'contactedOn'>('registeredOn'), sortDirection = ref<'asc' | 'desc'>('desc')
function sortDate(field: 'registeredOn' | 'contactedOn') { sortDirection.value = sortBy.value === field && sortDirection.value === 'asc' ? 'desc' : 'asc'; sortBy.value = field; void load(true) }
let generation=0
onBeforeUnmount(()=>generation++)
async function load(reset=false){if(reset)page.value=1;const ticket=++generation;busy.value=true;error.value='';try{const result=await autoflowApi.listRegisteredLeads({page:page.value,pageSize:pageSize.value,sortBy:sortBy.value,sortDirection:sortDirection.value,search:search.value||undefined,status:status.value||undefined,leadType:leadType.value||undefined});if(ticket!==generation)return;rows.value=result.items;total.value=result.total}catch(e){if(ticket===generation)error.value=message(e)}finally{if(ticket===generation)busy.value=false}}
function message(e:unknown){const value=(e as {message?:string|string[]})?.message;return Array.isArray(value)?value.join('；'):value||'操作失败，请重试'}
function openForm(){for(const key of Object.keys(draft))delete (draft as unknown as Record<string,unknown>)[key];Object.assign(draft,{brandName:'',country:'',storeUrl:'',registeredOn:new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai'}).format(new Date())});showForm.value=true;error.value='';notice.value=''}
async function save(){if(!draft.country){error.value='请选择国家';return}saving.value=true;error.value='';try{await autoflowApi.registerLead(Object.fromEntries(Object.entries(draft).filter(([,value])=>value!=='')) as unknown as RegisterLeadInput);showForm.value=false;notice.value='线索已登记';await load(true)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function template(){try{const blob=await autoflowApi.leadImportTemplate();const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='客户线索导入模板.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=message(e)}}
async function importFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(!/\.xlsx$/i.test(file.name)||file.size>5*1024*1024){error.value='请选择5MB以内的.xlsx文件';return}saving.value=true;error.value='';try{importResult.value=await autoflowApi.importLeads(file);await load(true)}catch(e){error.value=message(e)}finally{saving.value=false;if(fileInput.value)fileInput.value.value=''}}
function whatsapp(row:StoreLead){return row.contacts.find(c=>c.type==='whatsapp')?.value||''}
const safeLink=(url?:string|null)=>url&&/^https?:\/\//i.test(url)?url:undefined
onMounted(()=>load())
</script>
<template>
 <section class="lead-register panel">
  <div class="lead-toolbar">
   <div class="lead-actions"><button class="btn btn-primary lead-primary-action" :disabled="saving" @click="openForm">＋ 新增线索</button><button class="btn btn-secondary" :disabled="saving" @click="fileInput?.click()">{{ saving&&!showForm?'正在导入…':'Excel 导入' }}</button><button class="btn btn-ghost" @click="template">下载模板</button><input ref="fileInput" type="file" accept=".xlsx" class="hidden" aria-label="导入线索文件" @change="importFile" /></div>
   <form class="lead-filters" @submit.prevent="load(true)"><input v-model="search" class="input" placeholder="客户名称 / 店铺 / 国家 / 产品分类" aria-label="搜索线索" /><select v-model="leadType" class="input" aria-label="线索类型" @change="load(true)"><option value="">全部类型</option><option v-for="(label,value) in types" :key="value" :value="value">{{label}}</option></select><select v-model="status" class="input" aria-label="线索阶段" @change="load(true)"><option value="">全部阶段</option><option v-for="item in ['new','qualified','contacted','replied','opportunity','won','lost','invalid']" :key="item" :value="item">{{t(`status.${item}`)}}</option></select><button class="btn btn-secondary" :disabled="busy">查询</button></form>
  </div>
  <p v-if="error" role="alert" class="lead-error">{{error}}</p><p v-if="notice" role="status" class="lead-feedback">{{notice}}</p>
  <section v-if="importResult" class="lead-import-result" role="status"><strong>导入结果</strong> 共{{importResult.total}}行，成功{{importResult.created}}行，重复{{importResult.duplicates}}行，失败{{importResult.failed}}行。<button class="btn btn-ghost" @click="importResult=undefined">关闭</button><div class="import-errors"><p v-for="result in importResult.results.filter(r=>r.status!=='created')" :key="result.row">第{{result.row}}行：{{result.message}}</p></div></section>
  <div class="lead-table-scroll" :class="{ 'is-empty': !rows.length }" :aria-busy="busy"><table class="data-table lead-registration-table"><thead><tr><th>客户名称</th><th>线索类型</th><th>线索阶段</th><DateSortHeader label="登记日期" :direction="sortBy==='registeredOn'?sortDirection:undefined" :disabled="busy" @sort="sortDate('registeredOn')" /><th>业务员 / 登记人</th><DateSortHeader label="联系日期" :direction="sortBy==='contactedOn'?sortDirection:undefined" :disabled="busy" @sort="sortDate('contactedOn')" /><th>产品分类</th><th>国家 / 城市</th><th>Facebook</th><th>WhatsApp</th><th>店铺链接</th><th>目前跟进情况</th><th>下一步跟进计划</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><RouterLink :to="withReturnTo(`/leads/${row.id}`,route.fullPath)" class="lead-name">{{row.brandName}}</RouterLink></td><td><span class="lead-type">{{types[row.leadType||'automatic']}}</span></td><td><StatusBadge :status="row.status" /></td><td>{{row.registeredOn||row.createdAt.slice(0,10)}}</td><td>{{row.ownerName}}<small v-if="row.registrarName&&row.registrarName!==row.ownerName">{{row.registrarName}}</small></td><td>{{row.contactedOn}}</td><td>{{row.category}}</td><td>{{row.country}}<small>{{row.city}}</small></td><td><a v-if="safeLink(row.ownerFacebookUrl)" :href="safeLink(row.ownerFacebookUrl)" target="_blank" rel="noopener noreferrer" class="lead-url" :title="row.ownerFacebookUrl||undefined">{{row.ownerFacebookUrl}}</a></td><td>{{whatsapp(row)}}</td><td><a :href="safeLink(row.storeUrl)" target="_blank" rel="noopener noreferrer" class="lead-url" :title="row.storeUrl">{{row.storeUrl}}</a></td><td><span class="lead-long" :title="row.currentFollowUp">{{row.currentFollowUp}}</span></td><td><span class="lead-long" :title="row.nextFollowUpPlan">{{row.nextFollowUpPlan}}</span></td><td><GenerateOpportunityButton :lead-id="row.id" /></td></tr><tr v-if="!rows.length"><td colspan="14" class="lead-empty">{{busy?'正在加载…':'暂无匹配线索'}}</td></tr></tbody></table></div>
  <footer class="lead-pagination"><span>共 {{total}} 条线索</span><label>每页 <select v-model="pageSize" class="input" @change="load(true)"><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select></label><button class="btn btn-ghost" :disabled="busy||page===1" @click="page--;load()">上一页</button><span>{{page}} / {{Math.max(1,Math.ceil(total/pageSize))}}</span><button class="btn btn-ghost" :disabled="busy||page*pageSize>=total" @click="page++;load()">下一页</button></footer>
 </section>
 <div v-if="showForm" class="lead-modal-backdrop" @keydown.esc="!saving&&(showForm=false)"><section role="dialog" aria-modal="true" aria-labelledby="lead-register-title" class="lead-modal"><header><div><h2 id="lead-register-title">新增客户线索</h2><p>登记客户信息，持续跟进开发进度。</p></div><button class="btn btn-ghost" :disabled="saving" @click="showForm=false" aria-label="关闭登记窗口">×</button></header><form @submit.prevent="save"><div class="lead-form-grid"><label>客户名称 <b>*</b><input v-model="draft.brandName" autofocus required maxlength="160" class="input" /></label><label>线索类型<input value="手工录入" disabled class="input" /></label><label>国家 <b>*</b><CountryPicker v-model="draft.country" :clearable="false" /></label><label>城市<input v-model="draft.city" maxlength="120" class="input" /></label><label>登记日期<input v-model="draft.registeredOn" type="date" class="input" /></label><label>联系日期<input v-model="draft.contactedOn" type="date" class="input" /></label><label>产品分类<input v-model="draft.category" maxlength="120" class="input" /></label><label>WhatsApp<input v-model="draft.whatsapp" maxlength="80" class="input" placeholder="国家区号及号码" /></label><label class="wide">店铺链接 <b>*</b><input v-model="draft.storeUrl" type="url" required maxlength="500" class="input" placeholder="https://" /></label><label class="wide">Facebook链接<input v-model="draft.facebook" type="url" maxlength="500" class="input" placeholder="https://www.facebook.com/" /></label><label class="wide">目前跟进情况<textarea v-model="draft.currentFollowUp" maxlength="2000" rows="2" class="input" /></label><label class="wide">下一步跟进计划<textarea v-model="draft.nextFollowUpPlan" maxlength="2000" rows="2" class="input" /></label></div><p class="lead-feedback">业务员、登记人自动使用当前登录账号；线索阶段默认为新线索。</p><p v-if="error" class="lead-error" role="alert">{{error}}</p><footer><button type="button" class="btn btn-ghost" :disabled="saving" @click="showForm=false">取消</button><button class="btn btn-primary lead-primary-action" :disabled="saving">{{saving?'保存中…':'保存线索'}}</button></footer></form></section></div>
</template>
<style scoped>
.lead-register{overflow:hidden;display:flex;flex-direction:column;min-height:360px}.lead-toolbar{padding:20px;display:flex;flex-wrap:wrap;gap:16px;justify-content:space-between}.lead-actions,.lead-filters{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.lead-filters input{width:280px}.lead-filters select{width:130px}.lead-table-scroll{overflow:auto;flex:1}.lead-table-scroll.is-empty{display:flex;min-height:220px}.lead-table-scroll.is-empty .lead-registration-table{flex:1}.lead-table-scroll.is-empty thead{height:48px}.lead-registration-table{min-width:1780px;font-size:12px}.lead-registration-table th{white-space:nowrap}.lead-registration-table td{vertical-align:middle;max-width:220px}.lead-name{font-weight:600;color:var(--color-chart-link,var(--color-link))}.lead-type{white-space:nowrap;border:1px solid var(--color-border);border-radius:4px;padding:3px 6px;font-size:11px}.lead-url,.lead-long{display:block;max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.lead-url{color:var(--color-chart-link,var(--color-link))}small{display:block;color:var(--color-text-secondary);margin-top:3px}.lead-empty{text-align:center;padding:60px!important}.lead-pagination{display:flex;align-items:center;justify-content:flex-end;gap:15px;padding:16px 20px;border-top:1px solid var(--color-border);font-size:12px}.lead-pagination>span:first-child{margin-right:auto}.lead-pagination label{display:flex;align-items:center;gap:8px}.lead-pagination select{width:75px}.lead-feedback,.lead-error{padding:8px 20px;font-size:12px}.lead-error{color:#c25252}.lead-feedback{color:var(--color-text-secondary)}.lead-import-result{margin:0 20px 15px;padding:12px;border:1px solid var(--color-border);border-radius:6px;font-size:13px}.import-errors{max-height:150px;overflow:auto}.lead-modal-backdrop{position:fixed;inset:0;z-index:100;background:#10182766;display:flex;align-items:center;justify-content:center;padding:24px}.lead-modal{width:760px;max-width:100%;max-height:90vh;overflow:auto;background:var(--color-surface);color:var(--color-text);border:1px solid var(--color-border);border-radius:12px;box-shadow:0 18px 60px #0003}.lead-modal header{display:flex;justify-content:space-between;padding:20px 24px;border-bottom:1px solid var(--color-border)}.lead-modal h2{font-weight:700;font-size:18px}.lead-modal header p{font-size:12px;color:var(--color-text-secondary);margin-top:5px}.lead-form-grid{padding:20px 24px;display:grid;grid-template-columns:1fr 1fr;gap:16px}.lead-form-grid label{font-size:12px;display:block}.lead-form-grid input,.lead-form-grid textarea{margin-top:7px}.lead-form-grid .wide{grid-column:1/-1}.lead-form-grid b{color:#c25252}.lead-modal footer{display:flex;justify-content:flex-end;gap:10px;padding:16px 24px;border-top:1px solid var(--color-border)}@media(max-width:600px){.lead-form-grid{grid-template-columns:1fr}.lead-pagination{flex-wrap:wrap}.lead-filters input{width:100%}}
</style>
